using System.IO;using System.Windows;using Microsoft.EntityFrameworkCore;using Dentiva.Infrastructure.Data;namespace Dentiva.Desktop;public partial class App:Application{protected override void OnStartup(StartupEventArgs e){base.OnStartup(e);var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Dentiva");Directory.CreateDirectory(root);var o=new DbContextOptionsBuilder<DentivaDbContext>().UseSqlite($"Data Source={Path.Combine(root,"dentiva.db")}").Options;using var db=new DentivaDbContext(o);db.Database.Migrate();new MainWindow().Show();}}